  const rep = CHARS.split('');
  rep[43] = 'AV';
  let out2 = [];
  for (let k = 0; k < html.length; k++) {
    let code = html.charCodeAt(k);
    out2.push(code >= 0xE001 && code <= 0xE101 ? rep[code - 0xE001] : html.charAt(k));
  }
  java.setContent(out2.join(''));
  // 手打小说网族的.content类被站方推广框占用(ddouxs.com等链接), 正文在.conBox
