      .replace(/<p[^>]*>\s*本书由[^<]*<\/p>\s*<p[^>]*>\s*[^<]{1,25}\s*<\/p>/, '')
      .replace(/<p[^>]*>\s*(?:版权所有|侵权必究)\s*<\/p>/g, '')
      .replace(/<p[^>]*>\s*[·•]\s*<\/p>/g, '');
  }
  mainHtml;
}

