(function(){
if (!checkKey(key)) return '';
// 2601107 v9 会话级搜索节流：两次搜索最小间隔 2600ms，降低触发站点搜索风控的概率。
// 只作用于搜索链路（不设全局 concurrentRate，避免拖慢分页目录）；不主动探测搜索频率。
var _last = 0;
try { var _lv = String(source.get('rrssk_search_ts')); _last = (_lv === 'null' || _lv === 'undefined') ? 0 : (Number(_lv) || 0); } catch (eT0) {}
var _now = Date.now(), _wait = 2600 - (_now - _last);
if (_wait > 0 && _wait <= 2600) {
  try { Packages.java.lang.Thread.sleep(_wait); } catch (eT1) { var _t0 = Date.now(); while (Date.now() - _t0 < _wait) {} }
}
try { source.put('rrssk_search_ts', String(Date.now())); } catch (eT2) {}

// ===== 初始化 =====
if (!GET('server')) { 
    java.toast('init...');
    began();
}
let sourceUrl = GET('server');

java.longToast("当前域名: " + sourceUrl)
java.log(sourceUrl)
// 家族首页必须带移动UA(qmzw5/123wxwz的GoEdge WAF对默认UA的请求返回验证挑战页)
let home = String(java.ajax(sourceUrl + ',' + JSON.stringify({headers: JSON.stringify({'user-agent': MOBILE_UA})})));
if (/GOEDGE_WAF_CAPTCHA_ID/.test(home)) {
  java.toast('站点人机验证，请在弹窗中输入验证码');
  if (!goedgeVerify(sourceUrl, home)) throw new Error('人机验证未通过，请重新搜索');
  home = String(java.ajax(sourceUrl + ',' + JSON.stringify({headers: JSON.stringify({'user-agent': MOBILE_UA})})));
}
// rrssk家族为 window.location.href 跳转；菠萝猫为 window.open 跳转
let mm = home.match(/window\.location\.href=\'([^']+)/) || home.match(/window\.open\('([^']+)/);
if (!mm || !mm[1]) throw new Error('未找到搜索中转入口');
let url = mm[1];
java.log(url)
cookie.removeCookie(sourceUrl);
cookie.removeCookie(url)

let resp = java.get(url,{})
let cc = resp.headers().get("set-cookie")
cookie.setCookie(sourceUrl, cc)

let html = java.ajax(url)
let _t = html.match(/name="_t" value="(.*?)"/)[1];
java.log('_t: ' + _t)

function __enc(x) {
    return encodeURIComponent(x).replace(/[!'()*]/g, function(c) {
        return '%' + c.charCodeAt(0).toString(16).toUpperCase();
    });
}

// =========  提取服务器下发的签名算法（花括号配平法，兼容算法变体随机轮换） =========
let date = html.match(/action=signJs&v=(.*?)"/)[1];
let jsUrl = 'https://www.rrssk.com/?action=signJs&v=' + date;

java.log('jsUrl: ' + jsUrl)
let res = String(java.ajax(jsUrl))

let cre = /function\s*[\w$]*\s*\(([^)]*)\)\s*\{/g, cm, fn = null;
while ((cm = cre.exec(res)) !== null) {
  if (cm[1].split(",").length < 3) continue;
  let depth = 0, ci = cre.lastIndex - 1, cend = -1;
  for (; ci < res.length; ci++) {
    let ch = res.charAt(ci);
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (!depth) { cend = ci; break; } }
  }
  if (cend < 0) continue;
  let body = res.substring(cm.index, cend + 1);
  if (body.indexOf('=function') !== -1 && body.indexOf('slice(-8)') !== -1 && body.indexOf('charCodeAt') !== -1) { fn = body; break; }
}
if (!fn) throw new Error('签名函数提取失败，站点可能已更新');

// 环境检测变量替换为常量
let ere = /([\w$]+)!==(\d+)\)/g, em;
while ((em = ere.exec(res)) !== null) {
  if (fn.indexOf(em[1]) !== -1) { fn = fn.split(em[1]).join(em[2]); break; }
}
var q = eval('(' + fn + ')');

var ts = Math.floor(Date.now() / 1000);
var s = q(__enc(key), _t, ts);

let body = '_t='+_t+'&_ts='+ts+'&_s='+s+'&keyword='+__enc(key)

return baseHost + '/?action=search,'+JSON.stringify({"method": "POST", "body": body});
})()
